<script setup>import { computed,onMounted,ref } from 'vue';import { api } from '../api/ehr';const employees=ref([]),keyword=ref('');onMounted(async()=>employees.value=await api.employees());const filtered=computed(()=>employees.value.filter(x=>(x.fullName+x.employeeNo+x.departmentName+x.position).toLowerCase().includes(keyword.value.toLowerCase())));const labels={PROBATION:'试用',ACTIVE:'在职',LEAVE:'休假',TERMINATED:'离职'}</script>
<template><div class="page safe-top"><h1 class="page-title">员工花名册</h1><van-search v-model="keyword" shape="round" placeholder="搜索姓名、工号、部门或职位"/><section v-for="person in filtered" :key="person.id" class="person card"><div class="avatar">{{person.fullName.slice(0,1)}}</div><div class="info"><div class="list-title">{{person.fullName}} <span class="tag">{{labels[person.employmentStatus]}}</span></div><div class="muted">{{person.employeeNo}} · {{person.departmentName}} · {{person.position || '员工'}}</div><div class="contact">{{person.phone || '暂无电话'}} · {{person.email || '暂无邮箱'}}</div></div></section><div v-if="!filtered.length" class="empty">没有找到员工</div></div></template>
<style scoped>.van-search{padding:0 0 16px;background:transparent}.person{display:flex;align-items:center;gap:13px}.avatar{width:46px;height:46px;display:grid;place-items:center;border-radius:15px;background:#f1e5dc;color:var(--brand);font-weight:750}.info{flex:1;min-width:0}.tag{font-weight:400;margin-left:5px}.contact{margin-top:5px;color:#a08f86;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}</style>
